var default_branch;function get_branches(){var e=$("#github_branch");e.empty();var t=$("<option></option>");t.attr("value","").text("Not applicable"),e.append(t);var a=$("#github_url").val();a&&$.get(daGetGitBranches,{url:a},"json").done(function(a){if(!a.success)return e.empty(),(t=$("<option></option>")).attr("value","").text("Unable to fetch branches"),e.append(t),void console.error("get_branches failed: "+a.reason);if(a.success){var n=a.result.length;if(n>0){var r=default_branch,o=[default_branch,daGithubBranch,"master","main"];e:for(var u=0;u<4;u++)for(var c=0;c<n;c++)if(a.result[c].name==o[u]){r=o[u];break e}e.empty();for(c=0;c<n;c++)(t=$("<option></option>")).attr("value",a.result[c].name).text(a.result[c].name),a.result[c].name==r&&t.prop("selected",!0),$(e).append(t)}}})}document.addEventListener("DOMContentLoaded",function(){$(document).ready(function(){default_branch=daDefaultBranch,get_branches(),$("#github_url").on("change",get_branches)})});